class School:
    def __init__(self):
        self._students = {}
        self._added = []

    def add_student(self, name, grade):
        if name in self._students:
            self._added.append(False)
            return

        self._students[name] = grade
        self._added.append(True)

    def roster(self):
        return [
            name
            for name, _grade in sorted(
                self._students.items(),
                key=lambda item: (item[1], item[0]),
            )
        ]

    def grade(self, grade_number):
        return sorted(
            name
            for name, student_grade in self._students.items()
            if student_grade == grade_number
        )

    def added(self):
        return list(self._added)

